INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('f46e609e-2acb-43b0-9505-f1497f5df88c','1f7b817a-c705-4268-9ef8-b12da0418e78',5,'Serviços digitais inclusivos e sustentáveis','2 horas',NULL,NULL,NULL,'por_fornecer') ON CONFLICT DO NOTHING;
INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('6660fc55-fc87-4e8f-b9aa-62955f31d10b','3d0dd3a0-a53b-4800-a032-68527d708eb1',1,'Artigo 16 — Acessibilidade','20 minutos',NULL,'<h3>O que a lei exige</h3><p>A pessoa com deficiência tem direito de acesso ao ambiente físico, transporte, informação e tecnologias e sistemas de comunicação com base no desenho universal e ajustamento razoável.</p><h3>O que significa na prática para um servidor público</h3><p>Ao criar ou escolher um serviço, comece por torná-lo utilizável pelo maior número de pessoas. Quando uma pessoa ainda encontra uma barreira, faça o ajustamento adequado à sua necessidade.</p><h3>Exemplo concreto de serviço digital moçambicano</h3><p>No Portal do Governo de Moçambique, um formulário deve poder ser preenchido só com o teclado e lido por um leitor de ecrã.</p><p><strong>Fonte:</strong> Lei n.º 10/2024, de 7 de Junho, artigo 16.</p>',NULL,'disponivel') ON CONFLICT DO NOTHING;
INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('24874ec9-5867-4ce3-ae64-b0d7c0ced800','3d0dd3a0-a53b-4800-a032-68527d708eb1',2,'Artigo 17 — Direito à informação e comunicação','20 minutos',NULL,'<h3>O que a lei exige</h3><p>As entidades públicas e privadas que prestam serviços públicos devem procurar disponibilizar informação em formatos acessíveis. O Estado deve garantir formação de comunicadores e agentes do Estado em língua de sinais.</p><h3>O que significa na prática para um servidor público</h3><p>Publique a mesma informação em formatos que pessoas diferentes consigam usar. Use texto claro, documentos acessíveis, legendas, áudio e Língua de Sinais Moçambicana quando necessário.</p><h3>Exemplo concreto de serviço digital moçambicano</h3><p>Num aviso publicado num portal de um ministério, disponibilize texto acessível, versão áudio e vídeo com legendas e interpretação em Língua de Sinais Moçambicana.</p><p><strong>Fonte:</strong> Lei n.º 10/2024, de 7 de Junho, artigo 17.</p>',NULL,'disponivel') ON CONFLICT DO NOTHING;
INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('66b6f4c8-30c9-48bc-bf28-a7eff576617d','3d0dd3a0-a53b-4800-a032-68527d708eb1',3,'Artigo 20 — Aquisição de bens, serviços e obras','20 minutos',NULL,'<h3>O que a lei exige</h3><p>Os processos de contratação de empreitadas, fornecimento de bens e prestação de serviços devem ter em conta as necessidades da pessoa com deficiência.</p><h3>O que significa na prática para um servidor público</h3><p>Inclua requisitos de acessibilidade desde o caderno de encargos. Avalie esses requisitos antes de contratar. Verifique o seu cumprimento na entrega.</p><h3>Exemplo concreto de serviço digital moçambicano</h3><p>Na contratação de um sistema de marcação de consultas para uma unidade pública de saúde, exija navegação por teclado, compatibilidade com leitor de ecrã e atendimento alternativo acessível.</p><p><strong>Fonte:</strong> Lei n.º 10/2024, de 7 de Junho, artigo 20.</p>',NULL,'disponivel') ON CONFLICT DO NOTHING;
INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('3f989ad1-f8fc-483c-8864-f7238c862b48','3d0dd3a0-a53b-4800-a032-68527d708eb1',4,'Artigo 24 — Direito à educação','20 minutos',NULL,'<h3>O que a lei exige</h3><p>A pessoa com deficiência tem direito à educação em instituições públicas e privadas. O Estado deve adequar metodologias, materiais, infra-estruturas, mobiliário e equipamento. Deve também incluir matérias sobre deficiência na formação de professores, quadros administrativos e gestores.</p><h3>O que significa na prática para um servidor público</h3><p>Planeie a formação para diferentes formas de aprender e participar. Dê materiais acessíveis. Garanta que a sala, a plataforma e os equipamentos não criam barreiras.</p><h3>Exemplo concreto de serviço digital moçambicano</h3><p>Numa plataforma pública de ensino à distância, disponibilize os materiais em texto acessível e áudio. Legende os vídeos. Permita concluir as actividades sem usar o rato.</p><p><strong>Fonte:</strong> Lei n.º 10/2024, de 7 de Junho, artigo 24.</p>',NULL,'disponivel') ON CONFLICT DO NOTHING;
INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('847724fd-3c99-49c5-aa53-755857a14887','3d0dd3a0-a53b-4800-a032-68527d708eb1',5,'Artigo 30 — Colecta de dados','20 minutos',NULL,'<h3>O que a lei exige</h3><p>O Estado promove a recolha, a análise, o armazenamento e a divulgação de dados sobre pessoas com deficiência em todas as esferas da vida.</p><h3>O que significa na prática para um servidor público</h3><p>Recolha apenas os dados necessários, com uma finalidade clara. Proteja a informação individual. Use os dados agregados para melhorar políticas e serviços.</p><h3>Exemplo concreto de serviço digital moçambicano</h3><p>Num serviço digital de inscrição para formação pública, o tipo de deficiência é opcional e autodeclarado. A pessoa pode alterá-lo ou removê-lo. Os relatórios não identificam indivíduos.</p><p><strong>Fonte:</strong> Lei n.º 10/2024, de 7 de Junho, artigo 30.</p>',NULL,'disponivel') ON CONFLICT DO NOTHING;
INSERT INTO public.licoes (id,modulo_id,ordem,titulo,duracao,ilustracao_svg,conteudo_elearning,guiao_formador,estado_conteudo) VALUES ('7d4ead51-c222-4822-8217-d1f94098873a','3d0dd3a0-a53b-4800-a032-68527d708eb1',6,'Artigo 31 — Estatística','20 minutos',NULL,'<h3>O que a lei exige</h3><p>O Estado garante a produção estatística com indicadores que permitam desagregar os dados por sexo, idade, tipo de deficiência, causas, prevalência e outras variáveis relevantes.</p><h3>O que significa na prática para um servidor público</h3><p>Prepare os sistemas para produzir indicadores desagregados. Ao divulgar, proteja grupos pequenos para impedir a identificação das pessoas.</p><h3>Exemplo concreto de serviço digital moçambicano</h3><p>No Painel Nacional desta plataforma, os resultados podem ser cruzados por género e tipo de deficiência. Grupos com menos de cinco pessoas aparecem como informação insuficiente para divulgação.</p><p><strong>Fonte:</strong> Lei n.º 10/2024, de 7 de Junho, artigo 31.</p>',NULL,'disponivel') ON CONFLICT DO NOTHING;
